//! Generation of the documentation the model owns (R1, §27.5).
//!
//! The generated files are committed, so a reviewer sees the diff.
//! `cargo xtask validate-model` regenerates them in memory and fails if the
//! committed bytes differ, which is what makes the model the single source
//! rather than merely the first source.

use core::fmt::Write as _;

use crate::{Ids, Model};

/// Where the generated conformance table is committed.
pub const CONFORMANCE_PATH: &str = "CONFORMANCE.md";

/// Render `model/ids.toml` from the ID register.
///
/// In the first #111 slice this reproduces the committed bytes exactly,
/// header included, so the projection is additive: `cargo xtask
/// validate-registry` projects `model/src/Registry.lex.tex` and fails if the
/// committed `model/ids.toml` differs, while the existing hand-edit gates
/// stay in force until every open register branch has rebased.
pub fn render_ids(ids: &Ids) -> String {
    let mut out = String::new();
    let _ = writeln!(
        out,
        "# model/ids.toml --- the LexLean conformance ID register (R1)."
    );
    let _ = writeln!(out, "#");
    let _ = writeln!(
        out,
        "# Every row is copied byte-for-byte from the SPEC.md §31 table; `cargo xtask"
    );
    let _ = writeln!(
        out,
        "# validate-spec-links` fails if the two ever disagree (RP-07). CONFORMANCE.md"
    );
    let _ = writeln!(
        out,
        "# is generated from this file by `just model-write` and compared by the model"
    );
    let _ = writeln!(
        out,
        "# gate. Every ID is honesty level `build` (§27.3): constructed here and"
    );
    let _ = writeln!(out, "# validated against its oracle.");
    let _ = writeln!(out);
    let _ = writeln!(out, "spec = {}", quoted(&ids.spec));
    for row in &ids.id {
        let _ = writeln!(out);
        let _ = writeln!(out, "[[id]]");
        let _ = writeln!(out, "id = {}", quoted(&row.id));
        let _ = writeln!(out, "level = {}", quoted(row.level.as_str()));
        let _ = writeln!(out, "suite = {}", quoted(&row.suite));
        let _ = writeln!(out, "statement = {}", quoted(&row.statement));
    }
    out
}

/// Quote a string as a TOML (and JSON) basic string.
fn quoted(value: &str) -> String {
    serde_json::to_string(value).expect("serializing a Rust string cannot fail")
}

/// Render `CONFORMANCE.md` from the ID register.
///
/// The index is generated rather than written, so that an ID cannot exist in
/// the documentation without a register row, or in the register without
/// appearing in the documentation (R1, R2, §27.5).
pub fn render_conformance(model: &Model) -> String {
    let mut out = String::new();
    let w = &mut out;
    let _ = writeln!(
        w,
        "<!-- @generated by `cargo xtask validate-model --write` from model/ids.toml. -->"
    );
    let _ = writeln!(
        w,
        "<!-- Do not edit. R1: the model is the single source. -->"
    );
    let _ = writeln!(w);
    let _ = writeln!(w, "# CONFORMANCE");
    let _ = writeln!(w);
    let _ = writeln!(
        w,
        "The conformance ID register (SPEC.md §31). Every ID has exactly one scenario"
    );
    let _ = writeln!(
        w,
        "in `features/suites/` and exactly one test named `conformance_<id>`; a test"
    );
    let _ = writeln!(
        w,
        "naming an ID not listed here fails `cargo xtask validate-model`, and so does"
    );
    let _ = writeln!(w, "an ID listed here with no scenario or no test (§27.8).");
    let _ = writeln!(w);
    let _ = writeln!(w, "The three honesty levels (R2):");
    let _ = writeln!(w);
    let _ = writeln!(w, "| Level | Meaning |");
    let _ = writeln!(w, "| --- | --- |");
    let _ = writeln!(
        w,
        "| `some-true` | A fact reproduced from an authority. **Not established here.** |"
    );
    let _ = writeln!(
        w,
        "| `build` | Constructed here and validated against its oracle. Evidence, not a proof. |"
    );
    let _ = writeln!(w, "| `open` | Measured and reported. **Never asserted.** |");
    let _ = writeln!(w);
    let _ = writeln!(
        w,
        "`cargo xtask validate-model` fails if any code path emits a diagnostic"
    );
    let _ = writeln!(w, "the error registry does not sanction (R5, `ERRORS.md`).");

    // The classes are read off the register, not listed here. A list would be a
    // taxonomy this file asserts and the register does not have, and the first
    // symptom would be a heading with nothing under it --- a document claiming
    // coverage of a class that has no IDs. `suite` is the grouping the register
    // already carries, so it is the one used.
    let mut suites: Vec<&str> = model.ids.id.iter().map(|r| r.suite.as_str()).collect();
    suites.sort_unstable();
    suites.dedup();

    for suite in suites {
        let rows: Vec<_> = model.ids.id.iter().filter(|r| r.suite == suite).collect();
        if rows.is_empty() {
            continue;
        }
        let _ = writeln!(w);
        let _ = writeln!(w, "## {suite}");
        let _ = writeln!(w);
        let _ = writeln!(w, "| ID | Level | Statement |");
        let _ = writeln!(w, "| --- | --- | --- |");
        for r in rows {
            let statement = r.statement.replace('\n', " ").replace('|', "\\|");
            let _ = writeln!(
                w,
                "| `{}` | `{}` | {} |",
                r.id,
                r.level.as_str(),
                statement.trim()
            );
        }
    }

    let _ = writeln!(w);
    let _ = writeln!(w, "## Cited authorities");
    let _ = writeln!(w);
    let _ = writeln!(w, "Never re-derived, vendored, or gated on.");
    let _ = writeln!(w);
    let _ = writeln!(w, "| Authority | Citation | Evidence here |");
    let _ = writeln!(w, "| --- | --- | --- |");
    for a in &model.authorities.authority {
        let citation = a.citation.replace('\n', " ").replace('|', "\\|");
        let realized = if a.realized_by.is_empty() {
            "--".to_string()
        } else {
            a.realized_by
                .iter()
                .map(|i| format!("`{i}`"))
                .collect::<Vec<_>>()
                .join(", ")
        };
        let _ = writeln!(w, "| `{}` | {} | {realized} |", a.id, citation.trim());
    }

    let _ = writeln!(w);
    let _ = writeln!(w, "## Claims that are not conformance IDs");
    let _ = writeln!(w);
    let _ = writeln!(w, "| ID | Level | Claim |");
    let _ = writeln!(w, "| --- | --- | --- |");
    for c in &model.ledger.claim {
        let statement = c.statement.replace('\n', " ").replace('|', "\\|");
        let _ = writeln!(
            w,
            "| `{}` | `{}` | {} |",
            c.id,
            c.level.as_str(),
            statement.trim()
        );
    }

    out
}

/// Where the generated diagnostic registry documentation is committed.
pub const ERRORS_PATH: &str = "ERRORS.md";

/// Render `ERRORS.md` from the closed error registry (R1, §26.1).
pub fn render_errors(model: &Model) -> String {
    let mut out = String::new();
    let w = &mut out;
    let _ = writeln!(
        w,
        "<!-- @generated by `cargo xtask validate-model --write` from model/errors.toml. -->"
    );
    let _ = writeln!(
        w,
        "<!-- Do not edit. R1: the model is the single source. -->"
    );
    let _ = writeln!(w);
    let _ = writeln!(w, "# ERRORS");
    let _ = writeln!(w);
    let _ = writeln!(
        w,
        "The closed public diagnostic registry (SPEC.md §26). Every user-visible"
    );
    let _ = writeln!(
        w,
        "failure carries exactly one of these codes, emitted through a checked"
    );
    let _ = writeln!(
        w,
        "constructor whose argument is a compile-time literal; `validate-model`"
    );
    let _ = writeln!(
        w,
        "rejects an unregistered code in use and an unused registered code."
    );
    let _ = writeln!(w);
    let _ = writeln!(w, "`lexlean explain <CODE>` prints one entry.");
    for row in &model.errors.error {
        let _ = writeln!(w);
        let _ = writeln!(w, "## `{}` --- {}", row.code, row.title);
        let _ = writeln!(w);
        let _ = writeln!(w, "{}", row.statement);
        let _ = writeln!(w);
        let _ = writeln!(w, "Class: `{}`. Exit code: {}.", row.class, row.exit);
    }
    out
}
